ALTER TABLE "crm"."catalog_change_requests" ADD CONSTRAINT "catalog_change_requests_kind_target_type_check" CHECK (("crm"."catalog_change_requests"."kind" like 'model.%' and "crm"."catalog_change_requests"."target_type" = 'model') or ("crm"."catalog_change_requests"."kind" like 'trim.%' and "crm"."catalog_change_requests"."target_type" = 'trim') or ("crm"."catalog_change_requests"."kind" like 'option.%' and "crm"."catalog_change_requests"."target_type" = 'option'));